// State object to track cache status and expiration
class CacheState implements Serializable {
    private boolean cached;
    private long timestamp;
    private static final long CACHE_LIFETIME_MS = 12 * 60 * 60 * 1000; // 12 hours in milliseconds

    public CacheState(boolean cached, long timestamp) {
        this.cached = cached;
        this.timestamp = timestamp;
    }

    public boolean isExpired(long currentTime) {
        return (currentTime - timestamp) > CACHE_LIFETIME_MS;
    }

    public boolean getCached() {
        return cached;
    }

    public long getTimestamp() {
        return timestamp;
    }
}

